<?php use app\services\Ui;use app\services\Workflow;use app\services\Catalog;use yii\helpers\Html;$this->title='Arizalar · KPI';$r=Yii::$app->request; ?>
<div class="page-heading"><div><span class="eyebrow">FAOLIYAT VA DALILLAR</span><h1><?= $r->get('queue')?'Tekshiruv navbati':'Arizalar' ?></h1><p>Jami <?= (int)$total ?> ta ariza. Har bir qaror tarixda saqlanadi.</p></div><?= Html::a('＋ Yangi faoliyat',['kpi/create'],['class'=>'button']) ?></div>
<section class="card"><?= Html::beginForm(['kpi/applications'],'get',['class'=>'filters']) ?><?php if($r->get('queue'))echo Html::hiddenInput('queue',1); ?><?= Ui::input('Qidiruv','q',$r->get('q',''),'search',['placeholder'=>'Faoliyat, xodim yoki kod']) ?><?= Ui::select('Holat','status',$r->get('status'),[''=>'Barcha holatlar']+Workflow::STATUSES) ?><?= Ui::select('Davr','period',$r->get('period'),[''=>'Barcha davrlar']+array_column($periods,'name','id')) ?><?= Ui::select('Toifa','category',$r->get('category'),[''=>'Barcha toifalar']+Catalog::CATEGORIES) ?><label class="check"><?= Html::checkbox('mine',(bool)$r->get('mine'),['value'=>1]) ?> Faqat mening arizalarim</label><label class="check"><?= Html::checkbox('appeals',(bool)$r->get('appeals'),['value'=>1]) ?> Apellyatsiyali arizalar</label><button class="button secondary">Saralash</button><?= Html::endForm() ?><?= $this->render('_table',['rows'=>$rows]) ?><div class="pagination"><?php if($page>1)echo Html::a('← Oldingi',array_merge(['kpi/applications'],$r->get(),['page'=>$page-1]),['class'=>'button secondary']); ?><span><?= $page ?> / <?= max(1,(int)ceil($total/25)) ?></span><?php if($page*25<$total)echo Html::a('Keyingi →',array_merge(['kpi/applications'],$r->get(),['page'=>$page+1]),['class'=>'button secondary']); ?></div></section>
